CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'Maker', avatar_path text, printer_specs text NOT NULL DEFAULT '', materials text[] NOT NULL DEFAULT '{}', links text[] NOT NULL DEFAULT '{}');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (true);
CREATE POLICY profiles_edit ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','Maker')); RETURN NEW; END $$;
CREATE TRIGGER on_printbids_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.user_roles(user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role='admin'), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
CREATE TABLE public.jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL, title text NOT NULL CHECK(length(title) BETWEEN 3 AND 160), summary text NOT NULL DEFAULT '',quantity integer NOT NULL CHECK(quantity>0), deadline date NOT NULL, budget numeric CHECK(budget>=0), technology text NOT NULL DEFAULT 'Any', material text NOT NULL DEFAULT 'Any', fulfillment text NOT NULL DEFAULT 'Shipping' CHECK(fulfillment IN ('Shipping','Local pickup')), region text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','open','awarded')),bid_count integer NOT NULL DEFAULT 0 CHECK(bid_count BETWEEN 0 AND 5), awarded_maker uuid, image_key integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.jobs TO authenticated; GRANT SELECT ON public.jobs TO anon; GRANT ALL ON public.jobs TO service_role;
ALTER TABLE public.jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY preview_jobs ON public.jobs FOR SELECT TO anon,authenticated USING(status='open' OR owner_id=auth.uid() OR awarded_maker=auth.uid());
CREATE POLICY create_jobs ON public.jobs FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND status='draft' AND bid_count=0 AND awarded_maker IS NULL);
CREATE POLICY edit_jobs ON public.jobs FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE POLICY delete_drafts ON public.jobs FOR DELETE TO authenticated USING(owner_id=auth.uid() AND status='draft' AND bid_count=0);
CREATE TABLE public.job_details(job_id uuid PRIMARY KEY REFERENCES public.jobs(id) ON DELETE CASCADE,description text NOT NULL CHECK(length(description)<=10000),needs_design boolean NOT NULL DEFAULT false,files text[] NOT NULL DEFAULT '{}',questions text[] NOT NULL DEFAULT '{}' CHECK(cardinality(questions)<=5),technical_questions text[] NOT NULL DEFAULT '{}',technical_answers text[] NOT NULL DEFAULT '{}',ai_blocked text);
GRANT SELECT,INSERT,UPDATE ON public.job_details TO authenticated; GRANT ALL ON public.job_details TO service_role;
ALTER TABLE public.job_details ENABLE ROW LEVEL SECURITY;
CREATE POLICY details_read ON public.job_details FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND (j.status='open' OR j.owner_id=auth.uid() OR j.awarded_maker=auth.uid())));
CREATE POLICY details_create ON public.job_details FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND j.owner_id=auth.uid() AND j.bid_count=0));
CREATE POLICY details_edit ON public.job_details FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND j.owner_id=auth.uid() AND j.bid_count=0)) WITH CHECK(EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND j.owner_id=auth.uid() AND j.bid_count=0));
CREATE TABLE public.bids(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES public.jobs(id),maker_id uuid NOT NULL,printing numeric NOT NULL CHECK(printing>0),materials numeric NOT NULL CHECK(materials>=0),shipping numeric NOT NULL CHECK(shipping>=0),lead_days integer NOT NULL CHECK(lead_days>0),notes text NOT NULL DEFAULT '' CHECK(length(notes)<=3000),answers text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,maker_id));
GRANT SELECT,INSERT ON public.bids TO authenticated; GRANT ALL ON public.bids TO service_role;
ALTER TABLE public.bids ENABLE ROW LEVEL SECURITY;
CREATE POLICY sealed_bids ON public.bids FOR SELECT TO authenticated USING(maker_id=auth.uid() OR EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND j.owner_id=auth.uid()));
CREATE POLICY submit_bid ON public.bids FOR INSERT TO authenticated WITH CHECK(maker_id=auth.uid());
CREATE FUNCTION public.guard_bid() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.jobs; required integer; BEGIN SELECT * INTO j FROM public.jobs WHERE id=NEW.job_id FOR UPDATE; IF j.status<>'open' OR j.owner_id=NEW.maker_id OR j.bid_count>=5 THEN RAISE EXCEPTION 'This job is not accepting your bid'; END IF; SELECT cardinality(questions) INTO required FROM public.job_details WHERE job_id=j.id; IF cardinality(NEW.answers)<>coalesce(required,0) OR EXISTS(SELECT 1 FROM unnest(NEW.answers) a WHERE length(trim(a))=0) THEN RAISE EXCEPTION 'Answer every poster question'; END IF; UPDATE public.jobs SET bid_count=bid_count+1 WHERE id=j.id; RETURN NEW; END $$;
CREATE TRIGGER enforce_five_bids BEFORE INSERT ON public.bids FOR EACH ROW EXECUTE FUNCTION public.guard_bid();
CREATE FUNCTION public.guard_job() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('postgres','supabase_admin') THEN RETURN NEW; END IF; IF NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.bid_count<>OLD.bid_count OR NEW.awarded_maker IS DISTINCT FROM OLD.awarded_maker OR (OLD.bid_count>0 AND NEW IS DISTINCT FROM OLD) THEN RAISE EXCEPTION 'Job editing is locked after the first bid'; END IF; IF NEW.status='awarded' THEN RAISE EXCEPTION 'Use hire to award a job'; END IF; IF NEW.status='open' AND OLD.status='draft' AND NOT EXISTS(SELECT 1 FROM public.job_details d WHERE d.job_id=OLD.id AND cardinality(d.technical_questions) BETWEEN 2 AND 3 AND cardinality(d.technical_answers)=cardinality(d.technical_questions) AND NOT EXISTS(SELECT 1 FROM unnest(d.technical_answers) a WHERE trim(a)='') AND (d.needs_design OR cardinality(d.files)>0)) THEN RAISE EXCEPTION 'Complete files and technical follow-up before publishing'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_job BEFORE UPDATE ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.guard_job();
CREATE FUNCTION public.hire_bid(bid_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bids; j public.jobs; BEGIN SELECT * INTO b FROM public.bids WHERE id=bid_id; SELECT * INTO j FROM public.jobs WHERE id=b.job_id FOR UPDATE; IF auth.uid() IS NULL OR j.owner_id<>auth.uid() OR j.status<>'open' THEN RAISE EXCEPTION 'Only the poster can hire on an open job'; END IF; UPDATE public.jobs SET status='awarded',awarded_maker=b.maker_id WHERE id=j.id; END $$;
REVOKE ALL ON FUNCTION public.hire_bid(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.hire_bid(uuid) TO authenticated;
CREATE TABLE public.contact_cards(job_id uuid NOT NULL REFERENCES public.jobs(id),user_id uuid NOT NULL,side text NOT NULL CHECK(side IN ('client','maker')),phone text NOT NULL DEFAULT '',email text NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',tracking text NOT NULL DEFAULT '',PRIMARY KEY(job_id,side));
GRANT SELECT,INSERT,UPDATE ON public.contact_cards TO authenticated; GRANT ALL ON public.contact_cards TO service_role;
ALTER TABLE public.contact_cards ENABLE ROW LEVEL SECURITY;
CREATE POLICY contacts_read ON public.contact_cards FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND j.status='awarded' AND auth.uid() IN (j.owner_id,j.awarded_maker)));
CREATE POLICY contacts_insert ON public.contact_cards FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND j.status='awarded' AND ((side='client' AND j.owner_id=auth.uid()) OR (side='maker' AND j.awarded_maker=auth.uid()))));
CREATE POLICY contacts_update ON public.contact_cards FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND j.status='awarded' AND ((side='client' AND j.owner_id=auth.uid()) OR (side='maker' AND j.awarded_maker=auth.uid()))));
CREATE TABLE public.verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE,printer_specs text NOT NULL,materials text[] NOT NULL,photos text[] NOT NULL DEFAULT '{}',links text[] NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),review_notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.verifications TO authenticated; GRANT ALL ON public.verifications TO service_role;
ALTER TABLE public.verifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY verification_read ON public.verifications FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE POLICY verification_apply ON public.verifications FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND review_notes='');
CREATE POLICY verification_review ON public.verifications FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE FUNCTION public.verified_makers() RETURNS TABLE(user_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT user_id FROM public.verifications WHERE status='approved' $$;
REVOKE ALL ON FUNCTION public.verified_makers() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.verified_makers() TO authenticated;
CREATE POLICY files_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='print-files' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='print-files' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.is_admin() OR EXISTS(SELECT 1 FROM public.job_details d JOIN public.jobs j ON j.id=d.job_id WHERE name=ANY(d.files) AND (j.status='open' OR j.owner_id=auth.uid() OR j.awarded_maker=auth.uid()))));
